import json, hashlib
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
items=[]
def add(cat, sources, rows):
    for line in rows.strip().splitlines():
        if not line.strip(): continue
        p=line.split('|')
        assert len(p)==9,(cat,len(p),line)
        slug,zh,en,fam,tzh,ten,azh,aen,aliases=p
        items.append(dict(id=slug,category=cat,family=fam,name={'zh':zh,'en':en},technique={'zh':tzh,'en':ten},avoid={'zh':azh,'en':aen},aliases=aliases.split(';') if aliases else [],sources=sources,status='draft',version='0.1.0',authorship='IRO independently authored research recipe',promptEvidence='not-generated',examples=[],tags=['lab'] if cat=='lab' else ['restyle'],testedModels=[],modelStatus={'chatgpt':'untested','gemini':'untested','flux':'untested'}))
