# Canonicalize duplicate treatments: color variants are not separate styles.
merges={'ascii-tonal':'pixel-ascii-mosaic','felt-stop-motion':'needle-felt'}
for old,new in merges.items():
    original=next(x for x in items if x['id']==old)
    canonical=next(x for x in items if x['id']==new)
    canonical['aliases']+=original['aliases']+[original['name']['zh'],original['name']['en']]
items=[x for x in items if x['id'] not in merges]
# Editorial first page crosses media rather than showing only one category.
featured=['pixar-inspired-3d','pixel-16bit','shin-hanga','watercolor-wet','oil-impasto','rural-handdrawn','risograph','satin-stitch','stained-glass','ukiyo-e-nishiki','line-density','claymation','charcoal-mass','gongbi-color','layered-papercut','crochet-amigurumi','cyanotype','ligne-claire','impressionist','origami-facets','ova-1980s','persian-miniature','paper-quilling','art-nouveau']
rank={key:i for i,key in enumerate(featured)}
items.sort(key=lambda x:rank.get(x['id'],len(featured)))
# Source roles are explicit: these are discovery / technique references, not
# assertions that an upstream author wrote or tested a particular IRO recipe.
for i,s in enumerate(items):
    s['order']=i+1
    if s['category'] in ['japan','anime']: s['tags'].append('japan')
    if s['category']=='china': s['tags'].append('china')
    if s['category'] in ['drawing','print']: s['tags'].append('linework')
    if s['category'] in ['paper','textile','material']: s['tags'].append('tactile')
    if s['category'] in ['game','photography']: s['tags'].append('retro')
    if s['category'] in ['anime','animation','comics','illustration']: s['tags'].append('illustrated')
    s['preservation']='reinterpret' if s['category']=='lab' or s['id']=='pixel-isometric' else 'structure'
    s['limits']={'zh':'尚未生成统一原图例图；风格特征为独立编写的目标，不是效果保证。','en':'No same-input example yet. Style characteristics are authored targets, not guarantees.'}
    if s['id'] in ['silhouette-paper','chinese-papercut','geometric-abstraction','cubist-facets','pixel-1bit','continuous-line','wireframe']:
        s['limits']={'zh':'高度简化风格可能丢失面部细节；优先保留主要轮廓与身份线索，尚未实测。','en':'Strong abstraction may lose facial detail; prioritize silhouettes and identity cues. Untested.'}
    s['fingerprint']=hashlib.sha256((s['technique']['en']+'\n'+s['avoid']['en']).encode()).hexdigest()
assert len({x['id'] for x in items})==len(items)
(ROOT/'data/catalog.json').write_text(json.dumps(items,ensure_ascii=False,indent=2)+'\n')
print(f'Authored {len(items)} independent untested recipes across {len(set(s["category"] for s in items))} categories.')
